import{_ as a,o as s,c as t,aj as i}from"./chunks/framework.Ggue6pUD.js";const k=JSON.parse('{"title":"版本與升級","description":"","frontmatter":{},"headers":[],"relativePath":"guide/versioning.md","filePath":"guide/versioning.md"}'),d={name:"guide/versioning.md"};function n(l,e,o,h,r,p){return s(),t("div",null,[...e[0]||(e[0]=[i(`<h1 id="版本與升級" tabindex="-1">版本與升級 <a class="header-anchor" href="#版本與升級" aria-label="Permalink to &quot;版本與升級&quot;">​</a></h1><p>這篇說明設計系統的版本怎麼命名、去哪裡看每版改了什麼，以及使用端專案怎麼換到新版本。要升級設計系統、或想先試用還沒正式發布的改動時讀這篇。</p><h2 id="有哪些套件" tabindex="-1">有哪些套件 <a class="header-anchor" href="#有哪些套件" aria-label="Permalink to &quot;有哪些套件&quot;">​</a></h2><p>設計系統分成兩種套件，各自在自己的 GitHub repo 打版本 tag：</p><table tabindex="0"><thead><tr><th>套件</th><th>repo</th><th>放什麼</th></tr></thead><tbody><tr><td><code>@mendesky/ds</code>（本體）</td><td><a href="https://github.com/Mendesky/mendesky-ds" target="_blank" rel="noreferrer">mendesky-ds</a></td><td>跟框架無關的樣式、圖示、工具程式、元件規格、這個文件網站</td></tr><tr><td><code>@mendesky/ds-angular</code></td><td><a href="https://github.com/Mendesky/mendesky-ds-angular" target="_blank" rel="noreferrer">mendesky-ds-angular</a></td><td>Angular 元件與 Angular 用法</td></tr><tr><td><code>@mendesky/ds-vue</code>（試做中）</td><td><a href="https://github.com/Mendesky/mendesky-ds-vue" target="_blank" rel="noreferrer">mendesky-ds-vue</a></td><td>Vue 3 元件與 Vue 用法；目前只有 8 個元件，還不供專案安裝</td></tr></tbody></table><p>使用端只要裝自己框架的套件。框架套件會指定它搭配的本體版本，安裝時自動一起裝。兩種套件的版本號各自獨立。</p><h2 id="版本號" tabindex="-1">版本號 <a class="header-anchor" href="#版本號" aria-label="Permalink to &quot;版本號&quot;">​</a></h2><p>每個版本是 GitHub repo 上的一個 git tag。使用端安裝時，在網址的 <code>#</code> 後面指定 tag。</p><h3 id="正式版-vx-y-z" tabindex="-1">正式版：vX.Y.Z <a class="header-anchor" href="#正式版-vx-y-z" aria-label="Permalink to &quot;正式版：vX.Y.Z&quot;">​</a></h3><p>正式版的 tag 寫成 <code>vX.Y.Z</code>，例如 <code>v0.1.0</code>。使用端平常釘在正式版。</p><h3 id="預發布版-vx-y-z-beta-n" tabindex="-1">預發布版：vX.Y.Z-beta.N <a class="header-anchor" href="#預發布版-vx-y-z-beta-n" aria-label="Permalink to &quot;預發布版：vX.Y.Z-beta.N&quot;">​</a></h3><p>預發布版是某個正式版發布之前的試用版，tag 寫成 <code>vX.Y.Z-beta.N</code>：</p><ul><li><code>X.Y.Z</code> 是它之後要成為的正式版號。</li><li><code>N</code> 從 1 開始。同一個版號在正式發布前又有修改，就再打下一個號碼，例如 <code>v0.1.8-beta.1</code>、<code>v0.1.8-beta.2</code>、<code>v0.1.8-beta.3</code>，最後才是 <code>v0.1.8</code>。</li></ul><p>預發布版的用途是：改動還沒正式發布前，先讓使用端專案裝起來實際跑、確認沒問題。確認後發布正式版，使用端再把版本從預發布版換成正式版，例如從 <code>v0.1.8-beta.2</code> 換到 <code>v0.1.8</code>。</p><p>不是每個正式版之前都有預發布版。</p><h3 id="升哪一位" tabindex="-1">升哪一位 <a class="header-anchor" href="#升哪一位" aria-label="Permalink to &quot;升哪一位&quot;">​</a></h3><p>目前還在 <code>0.x</code>，第一位固定是 0。照下表決定升哪一位：</p><table tabindex="0"><thead><tr><th>改動</th><th>升哪一位</th><th>例子（Angular 套件）</th></tr></thead><tbody><tr><td>移除公開的元件或匯出、改既有屬性的意義</td><td>中間位，最後一位歸零</td><td><code>v0.8.4</code> → <code>v0.9.0</code>：移除 Year Month Picker</td></tr><tr><td>新增元件</td><td>中間位，最後一位歸零</td><td><code>v0.6.0</code> → <code>v0.7.0</code>：新增 Menu Item</td></tr><tr><td>修正、加屬性、只改規格或說明文字</td><td>最後一位</td><td><code>v0.8.3</code> → <code>v0.8.4</code>：進度條加不定狀態與小尺寸</td></tr></tbody></table><ul><li>同一個版本裡只要有一項要升中間位，這一版就升中間位。</li><li>版號在計畫階段就決定，預發布版的 tag 照這個版號打。等到發正式版才發現該升中間位，前面打的預發布版號就都對不上了。</li><li>兩種套件各自判斷。例如框架套件移除了一個元件、本體只刪掉那份規格，兩邊都算「移除公開的元件」，都升中間位。</li></ul><h3 id="誰來打-tag" tabindex="-1">誰來打 tag <a class="header-anchor" href="#誰來打-tag" aria-label="Permalink to &quot;誰來打 tag&quot;">​</a></h3><p>目前預發布版與正式版的 tag 都是由維護者人工建立的。</p><h2 id="每版改了什麼" tabindex="-1">每版改了什麼 <a class="header-anchor" href="#每版改了什麼" aria-label="Permalink to &quot;每版改了什麼&quot;">​</a></h2><p>本體的版本說明在 <a href="https://github.com/Mendesky/mendesky-ds/releases" target="_blank" rel="noreferrer">mendesky-ds 的 GitHub Releases</a>，文件網站上方導覽列的「版本說明」會連過去；框架套件的版本說明在各自 repo 的 Releases，例如 <a href="https://github.com/Mendesky/mendesky-ds-angular/releases" target="_blank" rel="noreferrer">mendesky-ds-angular</a>。</p><p>升級前，先讀目前版本到目標版本之間每一版的說明。</p><h2 id="看對應版本的文件" tabindex="-1">看對應版本的文件 <a class="header-anchor" href="#看對應版本的文件" aria-label="Permalink to &quot;看對應版本的文件&quot;">​</a></h2><p>文件網站跟著本體的版本走，為本體的每個正式版各保留一整套文件：</p><ul><li>右上角的版本選單可以切換版本。切換後會停在另一個版本的同一頁。</li><li>選單裡的 <code>main（開發中）</code> 是還沒發布的最新內容，不一定跟任何正式版相同。</li><li>網址的結構是 <code>/&lt;版本&gt;/</code>。元件的可操作範例在各框架的範例網站，從元件總覽的連結進去。</li><li>直接打開文件網站首頁，會轉到最新的正式版。</li><li>拆成本體與框架套件之前（<code>@mendesky/ds-angular</code> v0.2.0 以前）的文件，保留在<a href="https://mendesky.github.io/mendesky-ds-angular/v0.2.0/" target="_blank" rel="noreferrer">舊的文件網站</a>。舊網站的首頁現在會轉到這個網站，要看舊版請用版本網址。</li></ul><p>使用端釘在哪一版，就看哪一版的文件，屬性與用法才會對得上。</p><h2 id="升級步驟" tabindex="-1">升級步驟 <a class="header-anchor" href="#升級步驟" aria-label="Permalink to &quot;升級步驟&quot;">​</a></h2><p>目前只有 Angular 版可以安裝，以下以 Angular 套件為例。以下把 <code>vX.Y.Z</code> 換成要升到的版本。</p><h3 id="_1-指名安裝新版本" tabindex="-1">1. 指名安裝新版本 <a class="header-anchor" href="#_1-指名安裝新版本" aria-label="Permalink to &quot;1. 指名安裝新版本&quot;">​</a></h3><p>把 <code>package.json</code> 裡 <code>@mendesky/ds-angular</code> 的 tag 改成新版本，並用完整的套件來源指名安裝：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> i</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;github:Mendesky/mendesky-ds-angular#vX.Y.Z&quot;</span></span></code></pre></div><p>這個指令會同時更新 <code>package.json</code> 與 <code>package-lock.json</code>：</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;dependencies&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;@mendesky/ds-angular&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;github:Mendesky/mendesky-ds-angular#vX.Y.Z&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>裝完打開 <code>package-lock.json</code>，找到 <code>node_modules/@mendesky/ds-angular</code> 這一筆，確認 <code>resolved</code> 結尾的 commit 已經換成新 tag 指向的 commit。</p><p>本體 <code>@mendesky/ds</code> 會依新版框架套件指定的版本自動安裝，不用另外指定；<code>package-lock.json</code> 裡 <code>node_modules/@mendesky/ds</code> 那一筆會一起更新。</p><p>安裝結束時，postinstall 會自動刷新專案根目錄的 <code>mendesky-ds-angular</code> symlink，不用手動處理（設定方式見<a href="./getting-started.html">開始使用</a>）。</p><h3 id="_2-跑型別檢查與測試" tabindex="-1">2. 跑型別檢查與測試 <a class="header-anchor" href="#_2-跑型別檢查與測試" aria-label="Permalink to &quot;2. 跑型別檢查與測試&quot;">​</a></h3><p>設計系統是原始碼套件，新版的元件會跟你的專案一起編譯。換版後至少跑一次：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tsc</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --noEmit</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                 # 型別檢查</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ng</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --watch=false</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">        # 單元測試</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ng</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                     # 建置</span></span></code></pre></div><p>有錯誤時，對照該版的版本說明與新版的元件說明頁修正。</p><h3 id="_3-一起-commit" tabindex="-1">3. 一起 commit <a class="header-anchor" href="#_3-一起-commit" aria-label="Permalink to &quot;3. 一起 commit&quot;">​</a></h3><p><code>package.json</code> 與 <code>package-lock.json</code> 要放在同一個 commit。</p><h2 id="試用預發布版" tabindex="-1">試用預發布版 <a class="header-anchor" href="#試用預發布版" aria-label="Permalink to &quot;試用預發布版&quot;">​</a></h2><p>步驟跟升級一樣，只是 tag 換成預發布版：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> i</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;github:Mendesky/mendesky-ds-angular#vX.Y.Z-beta.N&quot;</span></span></code></pre></div><p>同一版號發布正式版後，再用同樣的方式換成正式版 <code>vX.Y.Z</code>。</p><h2 id="相關" tabindex="-1">相關 <a class="header-anchor" href="#相關" aria-label="Permalink to &quot;相關&quot;">​</a></h2><ul><li><a href="./getting-started.html">開始使用</a></li><li><a href="./contributing.html">貢獻</a></li><li><a href="./first-screen.html">第一個畫面</a></li></ul>`,50)])])}const g=a(d,[["render",n]]);export{k as __pageData,g as default};
